  const out = [];
  const stack = [];
  let node = root;
  while (node !== null || stack.length > 0) {
    while (node !== null) {                // go as far left as possible
      stack.push(node);
      node = node.left;
    }
    node = stack.pop();
    out.push(node.val);                    // its left side is done: visit
    node = node.right;                     // then handle its right side
  }
  return out;
}

